13	const listShadowableFilesForTheme = (directory, theme) => {
14	  const fullThemePath = path.join(directory, `node_modules`, theme, `src`)
15	  const shadowableThemeFiles = glob.sync(fullThemePath + `/**/*.*`, {
16	    follow: true,
17	  })
