32	const isDefaultExport = node => {
33	  if (!node || node.type !== `MemberExpression`) {
34	    return false
35	  }
36	
37	  const { object, property } = node
38	
39	  if (object.type !== `Identifier` || object.name !== `module`) return false
40	  if (property.type !== `Identifier` || property.name !== `exports`)
41	    return false
42	
43	  return true
44	}
