46	const getValueFromLiteral = node => {
47	  if (node.type === `StringLiteral`) {
48	    return node.value
49	  }
50	
51	  if (node.type === `TemplateLiteral`) {
52	    return node.quasis[0].value.raw
53	  }
54	
55	  return null
56	}
