58	const getNameForPlugin = node => {
59	  if (node.type === `StringLiteral` || node.type === `TemplateLiteral`) {
60	    return getValueFromLiteral(node)
61	  }
62	
63	  if (node.type === `ObjectExpression`) {
64	    const resolve = node.properties.find(p => p.key.name === `resolve`)
65	    return resolve ? getValueFromLiteral(resolve.value) : null
