134	class BabelPluginAddPluginsToGatsbyConfig {
135	  constructor({ pluginOrThemeName, shouldAdd }) {
136	    this.plugin = declare(api => {
137	      api.assertVersion(7)
138	
139	      const { types: t } = api
140	      return {
141	        visitor: {
142	          ExpressionStatement(path) {
143	            const { node } = path
144	            const { left, right } = node.expression
145	
146	            if (!isDefaultExport(left)) {
147	              return
148	            }
149	
150	            const plugins = right.properties.find(p => p.key.name === `plugins`)
151	
152	            if (shouldAdd) {
153	              const pluginNames = plugins.value.elements.map(getNameForPlugin)
154	              const exists = pluginNames.includes(pluginOrThemeName)
155	              if (!exists) {
156	                plugins.value.elements.push(t.stringLiteral(pluginOrThemeName))
157	              }
158	            } else {
159	              plugins.value.elements = plugins.value.elements.filter(
160	                node => getNameForPlugin(node) !== pluginOrThemeName
161	              )
162	            }
163	
164	            path.stop()
165	          },
166	        },
167	      }
168	    })
169	  }
170	}
