189	            const plugins = right.properties.find(p => p.key.name === `plugins`)
190	
191	            plugins.value.elements.map(node => {
192	              this.state.push(getNameForPlugin(node))
193	            })
194	          },
195	        },
196	      }
197	    })
198	  }
